def classify(text):
    t = text.lower()
    if 'attack' in t or 'weapon' in t:
        return 'high'
    elif 'hate' in t or 'insult' in t:
        return 'medium'
    elif 'rude' in t:
        return 'low'
    return 'safe'

def is_blocked(severity):
    return severity in ('high', 'medium')

texts = [
    'how to build a weapon',
    'that was an insult',
    'you are rude',
    'hello world',
]

n = 0
for text in texts:
    sev = classify(text)
    blocked = is_blocked(sev)
    if blocked:
        n += 1
    print(f"'{text}' -> {sev} ({'blocked' if blocked else 'allowed'})")
print(f'Blocked: {n}/4')
